@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(List<List<double>> grid) {
  if (grid.isEmpty) return [];
  int rows = grid.length;
  int cols = grid[0].length;
  if (cols == 0) return [];
  List<List<double>> peaks = [];
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      double h = grid[r][c];
      bool isPeak = true;
      if (r > 0 && grid[r - 1][c] >= h) isPeak = false;
      if (r < rows - 1 && grid[r + 1][c] >= h) isPeak = false;
      if (c > 0 && grid[r][c - 1] >= h) isPeak = false;
      if (c < cols - 1 && grid[r][c + 1] >= h) isPeak = false;
      if (isPeak) {
        peaks.add([r.toDouble(), c.toDouble(), h]);
      }
    }
  }
  peaks.sort((a, b) {
    if (b[2] != a[2]) return b[2].compareTo(a[2]);
    if (a[0] != b[0]) return a[0].compareTo(b[0]);
    return a[1].compareTo(b[1]);
  });
  return peaks.map((p) => '(${p[0].toInt()},${p[1].toInt()}):${p[2]}').toList();
}

