double fn0(List<int> signalStrengths) {
  if (signalStrengths.isEmpty) return 0.0;
  Map<String, int> bins = {
    'excellent': 0,
    'good': 0,
    'fair': 0,
    'poor': 0,
  };
  for (int strength in signalStrengths) {
    if (strength >= -50) {
      bins['excellent'] = bins['excellent']! + 1;
    } else if (strength >= -60) {
      bins['good'] = bins['good']! + 1;
    } else if (strength >= -70) {
      bins['fair'] = bins['fair']! + 1;
    } else {
      bins['poor'] = bins['poor']! + 1;
    }
  }
  int total = signalStrengths.length;
  double weightedSum = bins['excellent']! * 4.0 +
                       bins['good']! * 3.0 +
                       bins['fair']! * 2.0 +
                       bins['poor']! * 1.0;
  return weightedSum / total;
}

