void fn0() {



  String s1 = "leetcode";
  List<String> wordDict1 = ["leet", "code"];

  String s2 = "applepenapple";
  List<String> wordDict2 = ["apple", "pen"];

  String s3 = "catsandog";
  List<String> wordDict3 = ["cats", "dog", "sand", "and", "cat"];

  String s4 = "catsanddog";
  List<String> wordDict4 = ["cats", "dog", "sand", "and", "cat"];

  bool wordBreak(String s, List<String> wordDict) {

    Set<String> wordSet = wordDict.toSet();

    List<bool> dp = List.filled(s.length + 1, false);
    dp[0] = true; 

    for (int i = 1; i <= s.length; i++) {

      for (int j = 0; j < i; j++) {

        if (dp[j] && wordSet.contains(s.substring(j, i))) {
          dp[i] = true;
          break; 
        }
      }
    }

    return dp[s.length];
  }

  List<String> wordBreakII(String s, List<String> wordDict) {
    Set<String> wordSet = wordDict.toSet();
    Map<String, List<String>> memo = {};

    List<String> backtrack(String remaining) {

      if (memo.containsKey(remaining)) {
        return memo[remaining]!;
      }

      List<String> result = [];

      if (remaining.isEmpty) {
        result.add("");
        return result;
      }

      for (int i = 1; i <= remaining.length; i++) {
        String prefix = remaining.substring(0, i);

        if (wordSet.contains(prefix)) {
          String suffix = remaining.substring(i);
          List<String> suffixWays = backtrack(suffix);

          for (String way in suffixWays) {
            if (way.isEmpty) {
              result.add(prefix);
            } else {
              result.add("$prefix $way");
            }
          }
        }
      }

      memo[remaining] = result;
      return result;
    }

    return backtrack(s);
  }

  print("=== Word Break (Can Segment?) ===");
  print("String: '$s1', Dictionary: $wordDict1");
  print("Can segment: ${wordBreak(s1, wordDict1)}");
  print("");

  print("String: '$s2', Dictionary: $wordDict2");
  print("Can segment: ${wordBreak(s2, wordDict2)}");
  print("");

  print("String: '$s3', Dictionary: $wordDict3");
  print("Can segment: ${wordBreak(s3, wordDict3)}");
  print("");

  print("String: '$s4', Dictionary: $wordDict4");
  print("Can segment: ${wordBreak(s4, wordDict4)}");
  print("");

  print("=== Word Break II (All Segmentations) ===");

  String s5 = "catsanddog";
  List<String> wordDict5 = ["cat", "cats", "and", "sand", "dog"];
  List<String> segmentations = wordBreakII(s5, wordDict5);
  print("String: '$s5', Dictionary: $wordDict5");
  print("All possible segmentations:");
  for (String seg in segmentations) {
    print("  - $seg");
  }
  print("");

  String s6 = "pineapplepenapple";
  List<String> wordDict6 = ["apple", "pen", "applepen", "pine", "pineapple"];
  segmentations = wordBreakII(s6, wordDict6);
  print("String: '$s6', Dictionary: $wordDict6");
  print("All possible segmentations:");
  for (String seg in segmentations) {
    print("  - $seg");
  }
  print("");

  int minWordBreaks(String s, List<String> wordDict) {
    Set<String> wordSet = wordDict.toSet();
    int n = s.length;

    List<int> dp = List.filled(n + 1, n + 1); 
    dp[0] = 0; 

    for (int i = 1; i <= n; i++) {
      for (int j = 0; j < i; j++) {
        if (dp[j] != n + 1 && wordSet.contains(s.substring(j, i))) {
          dp[i] = dp[i] < dp[j] + 1 ? dp[i] : dp[j] + 1;
        }
      }
    }

    return dp[n] == n + 1 ? -1 : dp[n];
  }

  print("=== Minimum Word Breaks ===");
  print("String: '$s1', Dictionary: $wordDict1");
  int minBreaks = minWordBreaks(s1, wordDict1);
  print("Minimum words needed: ${minBreaks == -1 ? 'Cannot segment' : minBreaks}");
  print("");

  print("String: '$s4', Dictionary: $wordDict4");
  minBreaks = minWordBreaks(s4, wordDict4);
  print("Minimum words needed: ${minBreaks == -1 ? 'Cannot segment' : minBreaks}");
}

