import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<int> rolls) {

  int state = 0;
  int roundPoints = 0;
  double total = 0.0;

  for (int roll in rolls) {
    if (state == 2) {
      state = 0; 
    }

    if (state == 0) {
      if (roll == 1) {
        state = 2; 
      } else if (roll != 6) {
        roundPoints = roll;
        state = 1; 
      }

    } else if (state == 1) {
      if (roll == 1) {
        roundPoints = 0;
        state = 2; 
      } else if (roll == 6) {
        total += roundPoints * 0.5; 
        roundPoints = 0;
        state = 0; 
      } else {
        roundPoints += roll; 
      }
    }
  }

  return total;
}

