Map<String, int> fn0(String sequence) {
  List<String> valid = [];
  for (int i = 0; i < sequence.length; i++) {
    String ch = sequence[i].toUpperCase();
    if (ch == 'A' || ch == 'C' || ch == 'G' || ch == 'T') {
      valid.add(ch);
    }
  }
  if (valid.isEmpty) return {};
  List<String> deduped = [];
  deduped.add(valid[0]);
  for (int i = 1; i < valid.length; i++) {
    if (valid[i] != valid[i - 1]) {
      deduped.add(valid[i]);
    }
  }
  Map<String, int> counts = {'A': 0, 'C': 0, 'G': 0, 'T': 0};
  for (int i = 0; i < deduped.length - 1; i += 2) {
    if (i + 1 < deduped.length) {
      String b1 = deduped[i];
      String b2 = deduped[i + 1];
      if (b1 != b2) {
        counts[b1] = counts[b1]! + 1;
        counts[b2] = counts[b2]! + 1;
      }
    }
  }
  Map<String, int> result = {};
  counts.forEach((k, v) {
    if (v > 0) result[k] = v;
  });
  return result;
}

