Set<int> fn0(String dna) {
  final result = <int>{};
  int i = 0;
  while (i < dna.length) {
    final ch = dna[i];
    if (ch != 'A' && ch != 'C' && ch != 'G' && ch != 'T') {
      i++;
      continue;
    }
    final start = i;
    var gcCount = 0;
    while (i < dna.length) {
      final base = dna[i];
      if (base != 'A' && base != 'C' && base != 'G' && base != 'T') {
        break;
      }
      if (base == 'G' || base == 'C') {
        gcCount++;
      }
      i++;
    }
    final length = i - start;
    if (length >= 4 && gcCount * 2 > length) {
      result.add(start);
    }
  }
  return result;
}

