import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<int> positions) {
  Set<int> occupied = positions.toSet();
  Set<int> attacked = {};
  const offsets = [
    [1, 2], [1, -2], [-1, 2], [-1, -2],
    [2, 1], [2, -1], [-2, 1], [-2, -1],
  ];
  for (int pos in occupied) {
    int f = pos % 8;
    int r = pos ~/ 8;
    for (List<int> off in offsets) {
      int nf = f + off[0];
      int nr = r + off[1];
      if (nf >= 0 && nf < 8 && nr >= 0 && nr < 8) {
        int target = nr * 8 + nf;
        if (!occupied.contains(target)) {
          attacked.add(target);
        }
      }
    }
  }
  List<int> result = attacked.toList();
  result.sort();
  return result;
}

