import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  Map<int, List<int>> graph = {
    0: [1, 2],
    1: [0, 3, 4],
    2: [0, 5],
    3: [1],
    4: [1, 5],
    5: [2, 4]
  };

  Set<int> visited = {};

  List<int> traversalOrder = [];

  List<int> stack = [];

  void dfsRecursive(int node) {
    visited.add(node);
    traversalOrder.add(node);

    if (graph.containsKey(node)) {
      for (int neighbor in graph[node]!) {
        if (!visited.contains(neighbor)) {
          dfsRecursive(neighbor);
        }
      }
    }
  }

  void dfsIterative(int startNode) {
    Set<int> visitedIter = {};
    List<int> iterativeOrder = [];
    stack.add(startNode);

    while (stack.isNotEmpty) {
      int current = stack.removeLast();

      if (!visitedIter.contains(current)) {
        visitedIter.add(current);
        iterativeOrder.add(current);

        if (graph.containsKey(current)) {

          for (int i = graph[current]!.length - 1; i >= 0; i--) {
            int neighbor = graph[current]![i];
            if (!visitedIter.contains(neighbor)) {
              stack.add(neighbor);
            }
          }
        }
      }
    }

    print('Iterative DFS traversal: $iterativeOrder');
  }

  void findAllComponents() {
    Set<int> allVisited = {};
    List<List<int>> components = [];

    for (int node in graph.keys) {
      if (!allVisited.contains(node)) {
        Set<int> componentVisited = {};
        List<int> component = [];
        List<int> componentStack = [node];

        while (componentStack.isNotEmpty) {
          int current = componentStack.removeLast();

          if (!componentVisited.contains(current)) {
            componentVisited.add(current);
            component.add(current);
            allVisited.add(current);

            if (graph.containsKey(current)) {
              for (int neighbor in graph[current]!) {
                if (!componentVisited.contains(neighbor)) {
                  componentStack.add(neighbor);
                }
              }
            }
          }
        }

        components.add(component);
      }
    }

    print('\nConnected components:');
    for (int i = 0; i < components.length; i++) {
      print('Component ${i + 1}: ${components[i]}');
    }
  }

  bool hasPath(int start, int end) {
    if (!graph.containsKey(start) || !graph.containsKey(end)) {
      return false;
    }

    Set<int> pathVisited = {};
    List<int> pathStack = [start];

    while (pathStack.isNotEmpty) {
      int current = pathStack.removeLast();

      if (current == end) {
        return true;
      }

      if (!pathVisited.contains(current)) {
        pathVisited.add(current);

        if (graph.containsKey(current)) {
          for (int neighbor in graph[current]!) {
            if (!pathVisited.contains(neighbor)) {
              pathStack.add(neighbor);
            }
          }
        }
      }
    }

    return false;
  }

  print('Graph structure:');
  graph.forEach((node, neighbors) {
    print('Node $node -> $neighbors');
  });

  print('\n--- Depth-First Search Demo ---\n');

  print('Starting recursive DFS from node 0:');
  dfsRecursive(0);
  print('Recursive DFS traversal: $traversalOrder');

  print('\nStarting iterative DFS from node 0:');
  dfsIterative(0);

  findAllComponents();

  print('\n--- Path Existence Tests ---');
  print('Path from 0 to 5: ${hasPath(0, 5)}');
  print('Path from 3 to 5: ${hasPath(3, 5)}');
  print('Path from 3 to 2: ${hasPath(3, 2)}');

  Map<int, List<int>> disconnectedGraph = {
    0: [1],
    1: [0],
    2: [3],
    3: [2],
    4: []
  };

  print('\n--- Disconnected Graph Test ---');
  print('Disconnected graph structure:');
  disconnectedGraph.forEach((node, neighbors) {
    print('Node $node -> $neighbors');
  });

  Set<int> disconnectedVisited = {};
  List<List<int>> disconnectedComponents = [];

  for (int node in disconnectedGraph.keys) {
    if (!disconnectedVisited.contains(node)) {
      List<int> component = [];
      List<int> componentStack = [node];
      Set<int> componentVisited = {};

      while (componentStack.isNotEmpty) {
        int current = componentStack.removeLast();

        if (!componentVisited.contains(current)) {
          componentVisited.add(current);
          component.add(current);
          disconnectedVisited.add(current);

          if (disconnectedGraph.containsKey(current)) {
            for (int neighbor in disconnectedGraph[current]!) {
              if (!componentVisited.contains(neighbor)) {
                componentStack.add(neighbor);
              }
            }
          }
        }
      }

      disconnectedComponents.add(component);
    }
  }

  print('\nConnected components in disconnected graph:');
  for (int i = 0; i < disconnectedComponents.length; i++) {
    print('Component ${i + 1}: ${disconnectedComponents[i]}');
  }
}

