Set<int> fn0(int initialChampion, List<int> events) {
  int champion = initialChampion;
  Set<int> history = {initialChampion};
  List<int> undoStack = [];
  for (int event in events) {
    if (event == -1) {
      if (undoStack.isNotEmpty) {
        champion = undoStack.removeLast();
        history.add(champion);
      }
    } else if (event > 0) {
      undoStack.add(champion);
      if (event > champion) {
        champion = event;
      }
      history.add(champion);
    }
  }
  return history;
}

