import 'dart:async';
import 'dart:convert';

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0(List<String> args) {
  if (args.isEmpty) {
    print('Usage: dart run script.dart <N>');
    return;
  }

  int N;
  try {
    N = int.parse(args[0]);
    if (N < 1) {
      print('N must be a positive integer.');
      return;
    }
  } catch (e) {
    print('Invalid input: $e');
    return;
  }

  List<int> queens = List.filled(N, -1);

  bool isSafe(int row, int col) {
    for (int i = 0; i < row; i++) {
      if (queens[i] == col) {
        return false; 
      }
      if ((queens[i] - col).abs() == (row - i)) {
        return false; 
      }
    }
    return true;
  }

  void printBoard() {
    for (int i = 0; i < N; i++) {
      String row = '';
      for (int j = 0; j < N; j++) {
        row += (queens[i] == j) ? 'Q ' : '. ';
      }
      print(row.trim());
    }
    print('');
  }

  int solutions = 0;
  void solve(int row) {
    if (row == N) {
      solutions++;
      print('Solution $solutions:');
      printBoard();
      return;
    }

    for (int col = 0; col < N; col++) {
      if (isSafe(row, col)) {
        queens[row] = col;
        solve(row + 1);
        queens[row] = -1; 
      }
    }
  }

  print('Solving N-Queens for N=$N...');
  solve(0);
  print('Total solutions: $solutions');
}

