    if ((a == 'A' && b == 'T') || (a == 'T' && b == 'A') ||
        (a == 'G' && b == 'C') || (a == 'C' && b == 'G')) {
      pairScore = 0.5;
    }
    double current = prev1 > prev2 + pairScore ? prev1 : prev2 + pairScore;
    prev2 = prev1;
    prev1 = current;
  }
  return prev1;
}

