int fn0(List<int> scanLog) {
  final stack = <int>[];
  for (final digit in scanLog) {
    if (digit == 0) {
      if (stack.isNotEmpty) {
        stack.removeLast();
      }
    } else if (digit == 7) {
      if (stack.isNotEmpty) {
        stack.add(stack.last);
      }
    } else if (digit == 9) {
      if (stack.length >= 2) {
        final top = stack.removeLast();
        final next = stack.removeLast();
        stack.add(next * 10 + top);
      }
    } else if (digit >= 1 && digit <= 8) {
      stack.add(digit);
    }
  }
  var sum = 0;
  for (final value in stack) {
    sum += value;
  }
  return sum;
}

