import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(String barcode, int mask) {
  Set<int> result = <int>{};

  for (int i = 0; i < barcode.length; i++) {
    int digit = barcode.codeUnitAt(i) - 48;
    if (digit < 0 || digit > 9) {
      continue;
    }

    int shift = i % 4;
    int rotated = ((digit << shift) | (digit >> (4 - shift))) & 15;

    if (((mask >> digit) & 1) == 1) {
      rotated ^= 1;
    }

    int bits = 0;
    int value = rotated;
    while (value > 0) {
      bits += value & 1;
      value >>= 1;
    }

    if (bits % 2 == 0) {
      result.add(digit);
    } else if ((rotated & 8) != 0) {
      result.remove(digit);
    }
  }

  return result;
}

