import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(String input) {
  if (input.isEmpty) return {};
  final result = <String, int>{};
  final entries = input.split(';');
  for (var entry in entries) {
    final trimmed = entry.trim();
    if (trimmed.isEmpty) continue;
    int colonIndex = trimmed.indexOf(':');
    String name;
    int quantity;
    if (colonIndex == -1) {
      name = trimmed;
      quantity = 1;
    } else {
      name = trimmed.substring(0, colonIndex).trim();
      String qStr = trimmed.substring(colonIndex + 1).trim();
      if (qStr.isEmpty) {
        quantity = 1;
      } else {
        int? parsed = int.tryParse(qStr);
        if (parsed != null && parsed >= 0) {
          quantity = parsed;
        } else {
          quantity = 1;
        }
      }
    }
    if (name.isEmpty) continue;
    result[name] = (result[name] ?? 0) + quantity;
  }
  return result;
}

