List<int> fn0(List<int> entries, int windowSize, int targetSum) {
  if (entries.length < windowSize || windowSize <= 0) return [];
  List<int> result = [];
  int windowSum = 0;
  for (int i = 0; i < entries.length; i++) {
    windowSum += entries[i];
    if (i >= windowSize) {
      windowSum -= entries[i - windowSize];
    }
    if (i >= windowSize - 1 && windowSum == targetSum) {
      result.add(i - windowSize + 1);
    }
  }
  return result;
}

