import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<int> packets) {
  double avg(List<int> p, int start, int end) {
    final count = end - start;
    if (count == 0) return 0.0;
    if (count == 1) return p[start].toDouble();
    final mid = start + count ~/ 2;
    final left = avg(p, start, mid);
    final right = avg(p, mid, end);
    return (left * (mid - start) + right * (end - mid)) / count;
  }
  return avg(packets, 0, packets.length);
}

