  const raw = 'radar';
  print('\nRaw string        => "$raw"');
  print('Capitalized       => "${raw.capitalize()}"');
  print('Is palindrome?    => ${raw.isPalindrome}');

  final values = [1, 2, 3, 4, 5];
  print('\nValues            => $values');
  print('Sum               => ${values.sum}');
  print('Average           => ${values.average}');
}

