@pragma('vm:entry-point')
Map<String, int> fn0(List<int> actions) {
  List<int> stack = [];
  int completedRounds = 0;
  int totalScore = 0;
  for (int action in actions) {
    if (action > 0) {
      stack.add(action);
      if (stack.length >= 2) {
        int d2 = stack.removeLast();
        int d1 = stack.removeLast();
        int sum = d1 + d2;
        if (sum == 7 || sum == 11) {
          completedRounds += 1;
          totalScore += 15;
        } else {
          totalScore += sum;
          stack.add(d1);
          stack.add(d2);
        }
      }
    } else if (action == 0 && stack.isNotEmpty) {
      stack.removeLast();
    }
  }
  int remaining = stack.length;
  int finalScore = totalScore + (remaining ~/ 2);
  return {"completedRounds": completedRounds, "totalScore": finalScore, "remainingDice": remaining};
}

