import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  int n = 100;

  List<bool> isPrime = List.filled(n + 1, true);
  isPrime[0] = false; 
  isPrime[1] = false; 

  for (int i = 2; i * i <= n; i++) {

    if (isPrime[i]) {

      for (int j = i * i; j <= n; j += i) {
        isPrime[j] = false;
      }
    }
  }

  List<int> primes = [];
  for (int i = 2; i <= n; i++) {
    if (isPrime[i]) {
      primes.add(i);
    }
  }

  print('Prime numbers up to $n:');
  print(primes);
  print('Total count of primes: ${primes.length}');

  List<int> testNumbers = [17, 24, 29, 35, 47, 50, 73, 91, 97];
  print('\nPrimality test for specific numbers:');
  for (int num in testNumbers) {
    if (num <= n) {
      print('$num is ${isPrime[num] ? "prime" : "not prime"}');
    } else {
      print('$num is outside the range (> $n)');
    }
  }
}

