import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(List<String> entries) {
  List<int> stack = [];
  int balance = 0;
  List<String> audit = [];
  for (String e in entries) {
    if (e == '[') {
      stack.add(balance);
      balance = 0;
      audit.add('OPEN');
    } else if (e == ']') {
      int sub = balance;
      int parent = stack.isEmpty ? 0 : stack.removeLast();
      int result;
      if (sub >= 0) {
        result = parent + sub;
      } else {
        result = parent;
      }
      balance = result;
      audit.add('CLOSE:net=$sub,result=$result');
    } else if (e.startsWith('C:')) {
      balance += int.parse(e.substring(2));
    } else if (e.startsWith('D:')) {
      balance -= int.parse(e.substring(2));
    }
  }
  audit.add('FINAL:$balance');
  return audit;
}

