import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(String origin, int k) {
  int file = origin.codeUnitAt(0) - 97;
  int rank = origin.codeUnitAt(1) - 49;
  int low = 0;
  int high = 7;
  int d = 0;
  while (low <= high) {
    int mid = (low + high) ~/ 2;
    int cnt = 0;
    for (int f = 0; f < 8; f++) {
      for (int r = 0; r < 8; r++) {
        if ((f - file).abs() <= mid && (r - rank).abs() <= mid) cnt++;
      }
    }
    if (cnt >= k) {
      d = mid;
      high = mid - 1;
    } else {
      low = mid + 1;
    }
  }
  List<String> res = [];
  for (int f = 0; f < 8; f++) {
    for (int r = 0; r < 8; r++) {
      if ((f - file).abs() <= d && (r - rank).abs() <= d) {
        String sq = String.fromCharCode(97 + f) + (r + 1).toString();
        res.add(sq);
      }
    }
  }
  res.sort();
  return res.sublist(0, k);
}

