double fn0(List<List<int>> cells) {
  if (cells.isEmpty) return 0.0;
  int minSum = cells[0][0] + cells[0][1];
  int maxSum = minSum;
  int minDiff = cells[0][0] - cells[0][1];
  int maxDiff = minDiff;
  for (var cell in cells) {
    int sum = cell[0] + cell[1];
    int diff = cell[0] - cell[1];
    if (sum < minSum) minSum = sum;
    if (sum > maxSum) maxSum = sum;
    if (diff < minDiff) minDiff = diff;
    if (diff > maxDiff) maxDiff = diff;
  }
  int diameter = maxSum - minSum;
  int diffSpan = maxDiff - minDiff;
  if (diffSpan > diameter) diameter = diffSpan;
  return diameter.toDouble();
}

