import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<int> hashes, int maxLoad) {




  final cap = maxLoad < 1 ? 1 : maxLoad;
  final folded = <int>[];
  for (final h in hashes) {
    folded.add((h ^ (h >>> 16)) & 0xFFFF);
  }
  var n = 1;
  while (true) {
    final counts = List<int>.filled(n, 0);
    final distinct = List<Set<int>>.generate(n, (_) => <int>{});
    final mask = n - 1;
    for (final h in folded) {
      final idx = h & mask;
      counts[idx]++;
      distinct[idx].add(h);
    }
    var needSplit = false;
    for (var i = 0; i < n; i++) {
      if (counts[i] > cap && distinct[i].length > 1) {
        needSplit = true;
        break;
      }
    }
    if (!needSplit || n >= 1 << 16) {
      return counts;
    }
    n <<= 1;
  }
}

