int fn0(List<String> asciiRows) {
  if (asciiRows.isEmpty || asciiRows.any((row) => row.isEmpty)) {
    return 0;
  }
  int height = asciiRows.length;
  int width = asciiRows[0].length;
  for (var row in asciiRows) {
    if (row.length != width) return 0;
  }
  int count = 0;
  for (int y = 1; y < height - 1; y++) {
    for (int x = 1; x < width - 1; x++) {
      if (asciiRows[y][x] == '*') {
        bool top = asciiRows[y - 1][x] != ' ';
        bool bottom = asciiRows[y + 1][x] != ' ';
        bool left = asciiRows[y][x - 1] != ' ';
        bool right = asciiRows[y][x + 1] != ' ';
        if (top && bottom && left && right) {
          count++;
        }
      }
    }
  }
  return count;
}

