import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<String> matches) {
  final Map<String, int> losses = <String, int>{};
  final Map<String, int> eliminatedAt = <String, int>{};
  final Set<String> eliminated = <String>{};
  final Set<String> seenMatches = <String>{};

  for (final String raw in matches) {
    final List<String> parts = raw.split('|');
    if (parts.length != 3) {
      continue;
    }

    final int? stage = int.tryParse(parts[0].trim());
    final String winner = parts[1].trim();
    final String loser = parts[2].trim();

    if (stage == null || stage <= 0) {
      continue;
    }

    if (winner.isEmpty || loser.isEmpty || winner == loser) {
      continue;
    }

    final String signature = '$stage|$winner|$loser';
    if (seenMatches.contains(signature)) {
      continue;
    }
    seenMatches.add(signature);

    if (eliminated.contains(winner) || eliminated.contains(loser)) {
      continue;
    }

    losses[winner] = losses[winner] ?? 0;
    losses[loser] = (losses[loser] ?? 0) + 1;

    if (losses[loser] == 2) {
      eliminated.add(loser);
      eliminatedAt[loser] = stage;
    }
  }

  return eliminatedAt;
}

