@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(Map<String, int> perServing, int servings) {
  final scaled = <String, int>{};
  perServing.forEach((ingredient, amount) {
    scaled[ingredient] = amount * servings;
  });
  final entries = scaled.entries.toList();
  entries.sort((a, b) {
    final cmp = b.value.compareTo(a.value);
    if (cmp != 0) return cmp;
    return a.key.compareTo(b.key);
  });
  return Map.fromEntries(entries);
}

