Map<String, int> fn0(String bracket) {
  final wins = <String, int>{};
  final stack = <String>[];

  for (var i = 0; i < bracket.length; i++) {
    final ch = bracket[i];
    if (ch == '(') {
      stack.add('(');
    } else if (ch == ')') {
      final right = stack.removeLast();
      final left = stack.removeLast();
      stack.removeLast(); 
      final winner = left.codeUnitAt(0) >= right.codeUnitAt(0) ? left : right;
      wins[winner] = (wins[winner] ?? 0) + 1;
      stack.add(winner);
    } else if (ch.compareTo('A') >= 0 && ch.compareTo('Z') <= 0) {
      final player = ch;
      wins.putIfAbsent(player, () => 0);
      stack.add(player);
    }
  }

  return wins;
}

