import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  String text = "ABABDABACDABABCABAB";
  String pattern = "ABABCABAB";

  List<int> computeLPS(String pattern) {
    int m = pattern.length;
    List<int> lps = List.filled(m, 0);
    int len = 0;
    int i = 1;

    while (i < m) {
      if (pattern[i] == pattern[len]) {
        len++;
        lps[i] = len;
        i++;
      } else {
        if (len != 0) {
          len = lps[len - 1];
        } else {
          lps[i] = 0;
          i++;
        }
      }
    }
    return lps;
  }

  List<int> kmpSearch(String text, String pattern) {
    List<int> matches = [];
    int n = text.length;
    int m = pattern.length;

    if (m == 0) return matches;

    List<int> lps = computeLPS(pattern);

    int i = 0; 
    int j = 0; 

    while (i < n) {
      if (text[i] == pattern[j]) {
        i++;
        j++;
      }

      if (j == m) {
        matches.add(i - j);
        j = lps[j - 1];
      } else if (i < n && text[i] != pattern[j]) {
        if (j != 0) {
          j = lps[j - 1];
        } else {
          i++;
        }
      }
    }

    return matches;
  }

  print("Text: $text");
  print("Pattern: $pattern");
  print("Pattern length: ${pattern.length}");

  List<int> lps = computeLPS(pattern);
  print("\nLPS array for pattern:");
  for (int i = 0; i < pattern.length; i++) {
    print("  ${pattern[i]}: ${lps[i]}");
  }

  List<int> matches = kmpSearch(text, pattern);

  print("\nPattern found at indices: $matches");

  print("\nVerification:");
  for (int index in matches) {
    String matched = text.substring(index, index + pattern.length);
    print("  At index $index: '$matched'");
  }

  print("\n--- Additional Test Cases ---");

  String text1 = "AAABAAA";
  String pattern1 = "AAA";
  List<int> matches1 = kmpSearch(text1, pattern1);
  print("\nText: '$text1', Pattern: '$pattern1'");
  print("Matches at: $matches1");

  String text2 = "ABCDEFG";
  String pattern2 = "XYZ";
  List<int> matches2 = kmpSearch(text2, pattern2);
  print("\nText: '$text2', Pattern: '$pattern2'");
  print("Matches at: $matches2");

  String text3 = "AABAACAADAABAABA";
  String pattern3 = "A";
  List<int> matches3 = kmpSearch(text3, pattern3);
  print("\nText: '$text3', Pattern: '$pattern3'");
  print("Matches at: $matches3");

  String text4 = "AAAA";
  String pattern4 = "AA";
  List<int> matches4 = kmpSearch(text4, pattern4);
  print("\nText: '$text4', Pattern: '$pattern4'");
  print("Matches at: $matches4");
}

