@pragma('vm:never-inline')
@pragma('vm:entry-point')
BigInt fn0(BigInt n) {
  if (n == BigInt.zero) {
    return BigInt.one;
  }

  BigInt result = BigInt.one;
  for (BigInt i = n; i > BigInt.zero; i = i - BigInt.one) {
    result *= i;
  }

  return result;
}

