@pragma('vm:entry-point')
Map<String, int> fn0(List<int> itemFlags) {
  int inStock = 0;
  int fragileHazmat = 0;
  int singleFlagCount = 0;
  int allFlagsCount = 0;
  int noFlagsCount = 0;
  int xorChecksum = 0;
  int zoneConflict = 0;

  const int mask8 = 0xFF;
  const int inStockBit = 1;
  const int fragileBit = 2;
  const int tempControlledBit = 4;
  const int hazmatBit = 8;
  const int backorderBit = 16;

  for (int flags in itemFlags) {
    int masked = flags & mask8;
    xorChecksum ^= masked;

    if ((masked & inStockBit) != 0) inStock++;
    if ((masked & fragileBit) != 0 && (masked & hazmatBit) != 0) fragileHazmat++;
    if (masked == mask8) allFlagsCount++;
    if (masked == 0) noFlagsCount++;
    if ((masked & tempControlledBit) != 0 && (masked & backorderBit) != 0) zoneConflict++;

    if (masked != 0 && (masked & (masked - 1)) == 0) singleFlagCount++;
  }

  return {
    'inStock': inStock,
    'fragileHazmat': fragileHazmat,
    'singleFlagCount': singleFlagCount,
    'allFlagsCount': allFlagsCount,
    'noFlagsCount': noFlagsCount,
    'xorChecksum': xorChecksum,
    'zoneConflict': zoneConflict,
  };
}

