@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0(List<String> args) {
  final int n = args.isNotEmpty ? int.tryParse(args[0]) ?? 20 : 20;
  if (n < 0) {
    print('Please provide a non-negative integer (e.g., "dart run main.dart 20").');
    return;
  }

  final Map<int, BigInt> memo = {0: BigInt.zero, 1: BigInt.one};

  BigInt fib(int k) {
    final cached = memo[k];
    if (cached != null) return cached;
    final value = fib(k - 1) + fib(k - 2);
    memo[k] = value;
    return value;
  }

  for (int i = 0; i <= n; i++) {
    print('F($i) = ${fib(i)}');
  }
}

