void fn0() {

  int value = 0x12345678;

  print('Original value: 0x${value.toRadixString(16).toUpperCase()}');
  print('Binary: ${value.toRadixString(2).padLeft(32, '0')}');
  print('');

  List<int> toBigEndianBytes(int value) {
    return [
      (value >> 24) & 0xFF,
      (value >> 16) & 0xFF,
      (value >> 8) & 0xFF,
      value & 0xFF,
    ];
  }

  List<int> toLittleEndianBytes(int value) {
    return [
      value & 0xFF,
      (value >> 8) & 0xFF,
      (value >> 16) & 0xFF,
      (value >> 24) & 0xFF,
    ];
  }

  int fromBigEndianBytes(List<int> bytes) {
    return (bytes[0] << 24) | (bytes[1] << 16) | (bytes[2] << 8) | bytes[3];
  }

  int fromLittleEndianBytes(List<int> bytes) {
    return (bytes[3] << 24) | (bytes[2] << 16) | (bytes[1] << 8) | bytes[0];
  }

  int swap32(int value) {
    return ((value & 0xFF) << 24) |
           ((value & 0xFF00) << 8) |
           ((value & 0xFF0000) >> 8) |
           ((value >> 24) & 0xFF);
  }

  int swap16(int value) {
    return ((value & 0xFF) << 8) | ((value >> 8) & 0xFF);
  }

  bool isLittleEndian() {
    var bytes = toLittleEndianBytes(0x01020304);
    return bytes[0] == 0x04;
  }

  print('Big Endian Operations:');
  print('=' * 30);
  var bigEndianBytes = toBigEndianBytes(value);
  print('To bytes: [${bigEndianBytes.map((b) => '0x${b.toRadixString(16).toUpperCase().padLeft(2, '0')}').join(', ')}]');
  var reconstructedBE = fromBigEndianBytes(bigEndianBytes);
  print('From bytes: 0x${reconstructedBE.toRadixString(16).toUpperCase()}');
  print('');

  print('Little Endian Operations:');
  print('=' * 30);
  var littleEndianBytes = toLittleEndianBytes(value);
  print('To bytes: [${littleEndianBytes.map((b) => '0x${b.toRadixString(16).toUpperCase().padLeft(2, '0')}').join(', ')}]');
  var reconstructedLE = fromLittleEndianBytes(littleEndianBytes);
  print('From bytes: 0x${reconstructedLE.toRadixString(16).toUpperCase()}');
  print('');

  print('Endianness Swapping:');
  print('=' * 30);
  var swapped32 = swap32(value);
  print('32-bit swap of 0x${value.toRadixString(16).toUpperCase()}: 0x${swapped32.toRadixString(16).toUpperCase()}');
  var swappedBack = swap32(swapped32);
  print('Swap back: 0x${swappedBack.toRadixString(16).toUpperCase()}');

  int value16 = 0xABCD;
  var swapped16 = swap16(value16);
  print('16-bit swap of 0x${value16.toRadixString(16).toUpperCase()}: 0x${swapped16.toRadixString(16).toUpperCase()}');
  print('');

  print('System Information:');
  print('=' * 30);
  print('System is ${isLittleEndian() ? "Little Endian" : "Big Endian"}');
  print('');

  print('Network Byte Order Example:');
  print('=' * 30);
  int port = 8080;
  print('Host port: $port');

  var networkBytes = [(port >> 8) & 0xFF, port & 0xFF];
  print('Network bytes: [${networkBytes.map((b) => '0x${b.toRadixString(16).toUpperCase().padLeft(2, '0')}').join(', ')}]');

  int hostPort = (networkBytes[0] << 8) | networkBytes[1];
  print('Back to host: $hostPort');
  print('');

  print('Float Endianness Example:');
  print('=' * 30);
  double floatValue = 3.14159;

  var buffer = List<int>.filled(8, 0);
  var floatBits = floatValue.toString(); 
  print('Float value: $floatValue');

  int floatAsInt = 0x40490FDB; 
  var floatBE = toBigEndianBytes(floatAsInt);
  var floatLE = toLittleEndianBytes(floatAsInt);

  print('As Big Endian bytes: [${floatBE.map((b) => '0x${b.toRadixString(16).toUpperCase().padLeft(2, '0')}').join(', ')}]');
  print('As Little Endian bytes: [${floatLE.map((b) => '0x${b.toRadixString(16).toUpperCase().padLeft(2, '0')}').join(', ')}]');
  print('');

  print('Array Endianness Conversion:');
  print('=' * 30);
  List<int> data = [0x1234, 0x5678, 0xABCD, 0xEF01];
  print('Original 16-bit values: [${data.map((v) => '0x${v.toRadixString(16).toUpperCase()}').join(', ')}]');

  List<int> swappedData = data.map((v) => swap16(v)).toList();
  print('Swapped values: [${swappedData.map((v) => '0x${v.toRadixString(16).toUpperCase()}').join(', ')}]');

  List<int> byteStream = [];
  for (var val in data) {
    byteStream.add((val >> 8) & 0xFF);
