import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<int> packetSizes, int limit) {
  int left = 0;
  int right = packetSizes.length - 1;
  int bestIndex = -1;

  while (left <= right) {
    int mid = (left + right) ~/ 2;
    if (packetSizes[mid] <= limit) {
      bestIndex = mid;
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  return {
    'index': bestIndex,
    'size': bestIndex == -1 ? -1 : packetSizes[bestIndex]
  };
}

