import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
String fn0(int code) {

  int low = code & 0xFFF;
  int check = (code >> 12) & 0xF;
  int pop = 0;
  for (int i = 0; i < 12; i++) {
    if (((low >> i) & 1) == 1) {
      pop++;
    }
  }
  if (pop != check) {
    return 'INVALID';
  }
  int id = code & 0xFF;
  List<String> flags = [];
  if (((code >> 8) & 1) == 1) flags.add('RESERVED');
  if (((code >> 9) & 1) == 1) flags.add('FRAGILE');
  if (((code >> 10) & 1) == 1) flags.add('OVERSIZE');
  if (((code >> 11) & 1) == 1) flags.add('ARCHIVED');
  String flagPart = flags.isEmpty ? 'NONE' : flags.join('+');
  return 'S$id:$flagPart';
}

