import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<List<int>> grid, int dryThreshold) {
  if (grid.isEmpty) {
    return {
      'highestPriorityRow': -1,
      'lowestPriorityRow': -1,
      'rowsNeedingReview': 0,
    };
  }

  List<Map<String, int>> summaries = [];
  int reviewCount = 0;

  for (int i = 0; i < grid.length; i++) {
    List<int> row = grid[i];
    int dryCells = 0;
    int total = 0;
    int minValue = row[0];
    int maxValue = row[0];

    for (int value in row) {
      total += value;
      if (value <= dryThreshold) {
        dryCells++;
      }
      if (value < minValue) {
        minValue = value;
      }
      if (value > maxValue) {
        maxValue = value;
      }
    }

    if (dryCells * 2 >= row.length) {
      reviewCount++;
    }

    summaries.add({
      'index': i,
      'dryCells': dryCells,
      'range': maxValue - minValue,
      'total': total,
    });
  }

  summaries.sort((a, b) {
    if (a['dryCells'] != b['dryCells']) {
      return b['dryCells']!.compareTo(a['dryCells']!);
    }
    if (a['range'] != b['range']) {
      return b['range']!.compareTo(a['range']!);
    }
    if (a['total'] != b['total']) {
      return a['total']!.compareTo(b['total']!);
    }
    return a['index']!.compareTo(b['index']!);
  });

  return {
    'highestPriorityRow': summaries.first['index']!,
    'lowestPriorityRow': summaries.last['index']!,
    'rowsNeedingReview': reviewCount,
  };
}

