@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(int rows, int cols, int step) {
  if (rows <= 0 || cols <= 0) return [];
  int n = rows * cols;
  int a = n;
  int b = step;
  while (b != 0) {
    int temp = b;
    b = a % b;
    a = temp;
  }
  int count = n ~/ a;
  List<String> cells = [];
  for (int i = 0; i < count; i++) {
    int idx = (i * step) % n;
    cells.add('${idx ~/ cols},${idx % cols}');
  }
  cells.sort();
  return cells;
}

