import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<int> moistureLevels, int deficitThreshold) {
  if (moistureLevels.isEmpty) {
    return {'totalDeficitDays': 0, 'distinctIntervals': 0, 'longestInterval': 0};
  }
  int n = moistureLevels.length;
  List<int> starts = [];
  List<int> ends = [];
  bool inInterval = false;
  int start = -1;
  for (int day = 0; day < n; day++) {
    if (moistureLevels[day] < deficitThreshold) {
      if (!inInterval) {
        inInterval = true;
        start = day;
      }
    } else {
      if (inInterval) {
        inInterval = false;
        starts.add(start);
        ends.add(day - 1);
      }
    }
  }
  if (inInterval) {
    starts.add(start);
    ends.add(n - 1);
  }
  int totalDays = 0;
  int numIntervals = starts.length;
  int maxLen = 0;
  for (int i = 0; i < numIntervals; i++) {
    int len = ends[i] - starts[i] + 1;
    totalDays += len;
    if (len > maxLen) maxLen = len;
  }
  int merged = 0;
  if (numIntervals > 1) {
    for (int i = 1; i < numIntervals; i++) {
      if (starts[i] <= ends[i - 1] + 2) merged++;
    }
  }
  return {'totalDeficitDays': totalDays, 'distinctIntervals': numIntervals - merged, 'longestInterval': maxLen};
}

