double fn0(int rowByte) {
  const int ideal = 0x55; 
  final int diff = (rowByte & 0xFF) ^ ideal;
  int mismatches = 0;
  int mask = diff;
  while (mask != 0) {
    mismatches++;
    mask &= mask - 1;
  }
  return (8 - mismatches) / 8.0;
}

