import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<List<int>> mazeGrid) {
  int maxSegLen = 0;
  int minSegLen = 0;
  int totalPassable = 0;
  int maxSegScore = 0;
  int segCount = 0;
  bool foundFirst = false;

  for (int row = 0; row < mazeGrid.length; row++) {
    List<int> cells = mazeGrid[row];
    int left = 0;
    while (left < cells.length) {
      while (left < cells.length && cells[left] == -1) {
        left++;
      }
      if (left >= cells.length) break;
      int right = left;
      int segLen = 0;
      int segScore = 0;
      while (right < cells.length && cells[right] != -1) {
        segLen++;
        segScore += cells[right];
        right++;
      }
      totalPassable += segLen;
      segCount++;
      if (segLen > maxSegLen) maxSegLen = segLen;
      if (!foundFirst) {
        minSegLen = segLen;
        foundFirst = true;
      } else if (segLen < minSegLen) {
        minSegLen = segLen;
      }
      if (segScore > maxSegScore) maxSegScore = segScore;
      left = right;
    }
  }

  if (!foundFirst) {
    return {
      "maxSegmentLength": 0,
      "minSegmentLength": 0,
      "totalPassableCells": 0,
      "maxSegmentScore": 0,
      "segmentCount": 0
    };
  }

  return {
    "maxSegmentLength": maxSegLen,
    "minSegmentLength": minSegLen,
    "totalPassableCells": totalPassable,
    "maxSegmentScore": maxSegScore,
    "segmentCount": segCount
  };
}

