@pragma('vm:entry-point')
Map<String, int> fn0(List<int> sortedBarcodes, int targetBarcode) {
  int left = 0;
  int right = sortedBarcodes.length - 1;
  int nearestDiff = -1;
  int foundIndex = -1;

  while (left <= right) {
    int mid = left + (right - left) ~/ 2;
    int diff = (sortedBarcodes[mid] - targetBarcode).abs();

    if (nearestDiff == -1 || diff < nearestDiff) {
      nearestDiff = diff;
    }

    if (sortedBarcodes[mid] == targetBarcode) {
      foundIndex = mid;
      break;
    } else if (sortedBarcodes[mid] < targetBarcode) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  return {
    "found": foundIndex >= 0 ? 1 : 0,
    "index": foundIndex,
    "nearestDiff": nearestDiff
  };
}

