import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(String maze) {
  List<String> rows = maze.split('|');
  List<List<String>> grid = [];
  for (int i = 0; i < rows.length; i++) {
    grid.add(rows[i].split(','));
  }
  int numRows = grid.length;
  if (numRows == 0) return false;
  int numCols = grid[0].length;
  if (numCols == 0) return false;
  for (int r = 0; r < numRows; r++) {
    if (grid[r].length != numCols) return false;
  }
  for (int r = 0; r < numRows; r++) {
    for (int c = 0; c < numCols; c++) {
      String token = grid[r][c];
      Set<String> seen = {};
      for (int i = 0; i < token.length; i++) {
        String ch = token[i];
        if (ch != 'N' && ch != 'S' && ch != 'E' && ch != 'W') return false;
        if (!seen.add(ch)) return false;
      }
    }
  }
  for (int c = 0; c < numCols; c++) {
    if (grid[0][c].contains('N')) return false;
    if (grid[numRows - 1][c].contains('S')) return false;
  }
  for (int r = 0; r < numRows; r++) {
    if (grid[r][0].contains('W')) return false;
    if (grid[r][numCols - 1].contains('E')) return false;
  }
  for (int r = 0; r < numRows; r++) {
    for (int c = 0; c < numCols; c++) {
      String token = grid[r][c];
      if (c + 1 < numCols) {
        if (token.contains('E') != grid[r][c + 1].contains('W')) return false;
      }
      if (r + 1 < numRows) {
        if (token.contains('S') != grid[r + 1][c].contains('N')) return false;
      }
    }
  }
  return true;
}

