import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(String rle) {
  if (rle.isEmpty) return 0;
  int idx = 0;
  int checksum = 0;
  int i = 0;
  const int M = 104729;
  const int inv6 = 17455;

  int sumSq(int n) {
    if (n <= 0) return 0;
    int a = n % M;
    int b = (n + 1) % M;
    int c = (2 * n + 1) % M;
    int res = (a * b) % M;
    res = (res * c) % M;
    res = (res * inv6) % M;
    return res;
  }

  while (i < rle.length) {
    int start = i;
    while (i < rle.length && rle.codeUnitAt(i) >= 48 && rle.codeUnitAt(i) <= 57) {
      i++;
    }
    if (i == start) return -1;
    int count = int.parse(rle.substring(start, i));
    if (i >= rle.length) return -1;
    String color = rle[i];
    i++;
    if (color != 'W' && color != 'B') return -1;

    if (color == 'B' && count > 0) {
      int endIdx = idx + count;
      int total = (sumSq(endIdx) - sumSq(idx)) % M;
      if (total < 0) total += M;
      checksum = (checksum + total) % M;
    }
    idx += count;
  }
  return checksum;
}

