@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<int> cents, int targetRoundedCents) {
  if (cents.isEmpty || targetRoundedCents % 5 != 0) {
    return [-1, -1];
  }

  int L = targetRoundedCents - 2;
  int R = targetRoundedCents + 2;

  int minLen = 999999999;
  int maxLen = -1;

  int leftMin = 0;
  int sumMin = 0;
  int leftMax = 0;
  int sumMax = 0;

  for (int right = 0; right < cents.length; right++) {
    sumMin += cents[right];
    while (leftMin <= right && sumMin > R) {
      sumMin -= cents[leftMin];
      leftMin++;
    }

    sumMax += cents[right];
    while (leftMax <= right && sumMax >= L) {
      sumMax -= cents[leftMax];
      leftMax++;
    }

    if (leftMin <= leftMax - 1) {
      int currentMinLen = right - leftMax + 2;
      int currentMaxLen = right - leftMin + 1;
      if (currentMinLen < minLen) minLen = currentMinLen;
      if (currentMaxLen > maxLen) maxLen = currentMaxLen;
    }
  }

  if (maxLen == -1) {
    return [-1, -1];
  }

  return [minLen, maxLen];
}

