import 'dart:convert';
import 'dart:async';

@pragma('vm:never-inline')
@pragma('vm:entry-point')
Future<void> fn0() async {

  Stream<int> numberGenerator(int start, int end, Duration interval) async* {
    for (int i = start; i <= end; i++) {
      await Future.delayed(interval);
      yield i;
    }
  }

  Stream<int> oddFilter(Stream<int> input) async* {
    await for (var value in input) {
      if (value % 2 == 1) {
        yield value;
      }
    }
  }

  Stream<int> combinedOddStream() async* {
    yield* oddFilter(numberGenerator(1, 5, Duration(milliseconds: 500)));
    yield* oddFilter(numberGenerator(6, 10, Duration(milliseconds: 500)));
  }

  print('Starting combined odd number stream...');
  await for (var odd in combinedOddStream()) {
    print('Odd number: $odd');
  }
  print('Stream processing complete.');
}

